	@PreAuthorize("hasAnyRole('ROLE_APPROVER','ROLE_USER')")
    @PostMapping("/showvehicleinfo")
	@ApiOperation("This Method is to get by id")
	public ResponseEntity<CommonRes> getVehicleInfo(@RequestBody MotorVehicleInfoGetReq req,@RequestHeader("Authorization") String tokens)
	{
		CommonRes data = new CommonRes();
		MotorVehicleInfoRes res = new MotorVehicleInfoRes();
		
		if(StringUtils.isNotBlank(req.getInsuranceId()) && req.getInsuranceId().equalsIgnoreCase("100004") || req.getInsuranceId().equalsIgnoreCase("100046") ) {
			res = entityService.getVehicleInfoExternal(req,tokens);
		}else {
			res = entityService.getVehicleInfo(req,tokens);
			
			
		}
		
		
		
		if (res != null) {
			
			if (Boolean.TRUE.equals(res.getIsError())) {
		        data.setCommonResponse(null);
		        data.setErrorMessage(res.getErrorMessage1());
		        data.setIsError(true);
		        data.setMessage("Failed");
		        return new ResponseEntity<>(data, HttpStatus.CREATED);
		    }
			
			if(req.getSavedFrom().equalsIgnoreCase("API")) {
				List<Error> error = new ArrayList<Error>();
				RtsaMakeBodyError rtsaMakeBody = entityService.getRtsaMakeBodyTable(res.getResRegNumber());
				if(rtsaMakeBody!=null && StringUtils.isNotBlank(rtsaMakeBody.getErrorMessage())&& !req.getInsuranceId().equalsIgnoreCase("100019")) {
					error.add(new Error("2359", "Make / Body", rtsaMakeBody.getErrorMessage()));
				}else {
					String makeId = null;MotorBodyTypeMaster bodyData=null;

					System.out.println(
					    "TIRA RAW MAKE VALUES => resMakeName='"
					    
					    + "', resMake='"
					    + res.getResMake()
					    + "'"
					);
					if(StringUtils.isNotBlank(res.getResMake()))
						makeId = eserMotDetServImpl.getMotorMakeId(req.getInsuranceId(), req.getBranchCode(), res.getResMake());
					if(StringUtils.isNotBlank(res.getResBodyType()) && !req.getInsuranceId().equalsIgnoreCase("100019"))
						bodyData = eserMotDetServImpl.getBodyTypeId(req.getInsuranceId(), req.getBranchCode(), res.getResBodyType());
						if((StringUtils.isBlank(makeId) || (bodyData==null || StringUtils.isBlank(bodyData.getBodyNameEn())))) {
							if(StringUtils.isBlank(makeId)) {
								error.add(new Error("2357", "Make", "Make is not accessible in Master. Update the make master ( Make Name : "+res.getResMake()+" )"));
							}
							if((bodyData==null || StringUtils.isBlank(bodyData.getBodyNameEn())) && !req.getInsuranceId().equalsIgnoreCase("100019")) {
								error.add(new Error("2358", "BodyType", "BodyType is not accessible in Master. Update the Body Type master ( Body Name : "+res.getResBodyType()+" )"));
							}
						}
				}
				if(error != null && error.size() > 0) {
					entityService.updateRtsaMakeBodyTable(res,error);
					data.setCommonResponse(null);
					data.setErrorMessage(error);
					data.setIsError(true);
					data.setMessage("Failed");
					return new ResponseEntity<>(data, HttpStatus.CREATED);
				}
			}
			
			data.setCommonResponse(res);
			data.setErrorMessage(Collections.emptyList());
			data.setIsError(false);
			data.setMessage("Success");
			return new ResponseEntity<CommonRes>(data, HttpStatus.CREATED);
	
		} else {
			// Find Error Table
			List<Error> error =  entityService.getSearchErrorDetails(req);
			
//			List<Error> error = new ArrayList<Error>();
//			error.add(new Error("01","Not Found", "No Data Found"));
			data.setCommonResponse(res);
			data.setErrorMessage(error);
			data.setIsError(true);
			data.setMessage("Failed");
			return new ResponseEntity<>(data, HttpStatus.CREATED);
		}
	}
	
	
	
